  "behavior": "compute",
  "sql": "WITH cur AS (SELECT SUM(net_paid_usd) AS s FROM msb_store_sales WHERE i_category = 'Books' AND d_date BETWEEN DATE '1999-07-02' AND DATE '1999-07-31'), prior AS (SELECT SUM(net_paid_usd) AS s, COUNT(DISTINCT ss_ticket_number) AS t FROM msb_store_sales WHERE i_category = 'Books' AND d_date BETWEEN DATE '1998-07-02' AND DATE '1998-07-31') SELECT CASE WHEN prior.t < 5 OR prior.s IS NULL OR prior.s = 0 THEN NULL ELSE (cur.s - prior.s) / prior.s END AS yoy_growth_
